def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = tuple(pair[0] for pair in history)
    op = tuple(pair[1] for pair in history)

    last_my = my[-1]
    last_opp = op[-1]

    opp_def = sum(1 for x in op if x == 'D')

    streakD = 0
    idx = n - 1
    while idx >= 0 and op[idx] == 'D':
        streakD += 1
        idx -= 1

    start5 = n - 5
    if start5 < 0:
        start5 = 0
    recent5_def = sum(1 for x in op[start5:] if x == 'D')

    start10 = n - 10
    if start10 < 0:
        start10 = 0
    recent10_def = sum(1 for x in op[start10:] if x == 'D')

    tolerated = False
    lo = n - 7
    if lo < 0:
        lo = 0
    for j in range(lo, n - 1):
        if my[j] == 'D' and op[j + 1] == 'C':
            tolerated = True
            break

    if recent10_def >= 7 or (n >= 25 and opp_def * 10 >= n * 7):
        return 'D'

    if last_opp == 'C':
        if tolerated and recent5_def <= 3:
            return 'D'

        if last_my == 'D':
            return 'C'

        if opp_def == 0:
            if n >= 15:
                p = 0.04 if n < 50 else 0.08
                if rng.random() < p:
                    return 'D'
            return 'C'

        if recent10_def <= 2 and opp_def <= max(3, n // 5):
            if rng.random() < 0.02:
                return 'D'
            return 'C'

        if recent5_def >= 2 and rng.random() < 0.07:
            return 'D'

        return 'C'

    if last_my == 'D':
        if streakD >= 5:
            return 'D'
        return 'C'

    if streakD >= 3:
        return 'D'

    if opp_def <= max(2, int(0.25 * n)) and recent10_def <= 3:
        return 'C'

    return 'D' if rng.random() < 0.35 else 'C'
